def compute(vars):
    cash = vars["v1"]
    short_term_investments = vars["v2"]
    accounts_receivable = vars["v3"]
    current_liabilities = vars["v4"]

    quick_assets = sum((cash, short_term_investments, accounts_receivable))

    if current_liabilities == 0:
        return None

    quick_ratio = quick_assets / current_liabilities

    return {
        "value": round(quick_ratio, 2),
        "trace": {
            "Cash": cash,
            "Short-term Investments": short_term_investments,
            "Accounts Receivable": accounts_receivable,
            "Current Liabilities": current_liabilities,
            "Quick Assets": quick_assets,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
